func TestWriteMethodsEncodeStructuredBodyOnce(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Fatalf("read body: %v", err)
		}
		if len(body) == 0 || body[0] != '{' {
			t.Errorf("%s body must be a JSON object, got %q", r.Method, body)
		}
		var decoded map[string]any
		if err := json.Unmarshal(body, &decoded); err != nil {
			t.Errorf("decode %s body: %v", r.Method, err)
		}
		if decoded["requestedShipment"] == nil {
			t.Errorf("%s body lost requestedShipment: %#v", r.Method, decoded)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(server.Close)

	client := newRetryTestClient(server.URL)
	client.HTTPClient = server.Client()
	body := map[string]any{"requestedShipment": map[string]any{"serviceType": "FEDEX_GROUND"}}

	for _, method := range []string{http.MethodPost, http.MethodPut, http.MethodPatch} {
		t.Run(method, func(t *testing.T) {
			authorizeTestMutation(t, client, method, "/test", body)
			var err error
			switch method {
			case http.MethodPost:
				_, _, err = client.Post("/test", body)
			case http.MethodPut:
				_, _, err = client.Put("/test", body)
			case http.MethodPatch:
				_, _, err = client.Patch("/test", body)
			}
			if err != nil {
				t.Fatalf("%s request: %v", method, err)
			}
		})
	}
}

